"""Auto-generated ``FINDINGS.md`` for a run directory.

The file is regenerated by ``fbench analyze``; anything written below the
``## Notes`` heading is preserved across regenerations.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

NOTES_HEADING = "## Notes"


def _fmt(value: Any) -> str:
    if isinstance(value, float):
        return f"{value:.6g}"
    if isinstance(value, (list, dict)):
        text = json.dumps(value)
        return text if len(text) <= 60 else text[:57] + "..."
    return str(value)


def _threshold_text(th: dict[str, Any] | None) -> str:
    if not th:
        return ""
    parts = []
    if "min" in th:
        parts.append(f">= {th['min']}")
    if "max" in th:
        parts.append(f"<= {th['max']}")
    if "eq" in th:
        parts.append(f"== {th['eq']}")
    if th.get("severity") == "warn":
        parts.append("(warn)")
    return " ".join(parts)


def render(result: dict[str, Any], failed: list[str] | None = None, notes: str | None = None
           ) -> str:
    failed_names = {f.split("=", 1)[0] for f in failed or []}
    lines = [f"# {result['test']} — {result['verdict'].upper()}", ""]
    lines.append(f"**Run:** `{result['run_id']}` · **Started:** {result['started']} · "
                 f"**Ended:** {result['ended']}")
    lines.append("")
    unit_bits = []
    for name, u in (result.get("units") or {}).items():
        unit_bits.append(f"{name} ({u.get('label') or '-'}, {u.get('transceiver') or '?'}, "
                         f"image {u.get('image')}, serial {u.get('serial')}, "
                         f"build {u.get('build')})")
    lines.append("**Units:** " + ("; ".join(unit_bits) if unit_bits else "-"))
    lines.append("")
    lines.append(f"**Maintenance mode:** {'yes' if result.get('maintenance_mode') else 'no'} · "
                 f"**TX used:** {'yes' if result.get('tx_used') else 'no'}")
    lines += ["", "## Summary", "", result.get("summary") or "-", ""]
    metrics = result.get("metrics") or {}
    thresholds = result.get("thresholds") or {}
    lines += ["## Metrics", ""]
    if metrics:
        lines += ["| Metric | Value | Threshold | Status |", "|---|---|---|---|"]
        for name, value in metrics.items():
            th = thresholds.get(name)
            status = ""
            if th:
                status = "FAIL" if name in failed_names else "ok"
            lines.append(f"| `{name}` | {_fmt(value)} | {_threshold_text(th)} | {status} |")
    else:
        lines.append("None recorded.")
    lines.append("")
    for title, key in (("Warnings", "warnings"), ("Errors", "errors")):
        items = result.get(key) or []
        lines += [f"## {title}", ""]
        if items:
            lines += [f"- {x}" for x in items]
        else:
            lines.append("None.")
        lines.append("")
    lines += ["## Artifacts", ""]
    arts = result.get("artifacts") or []
    lines += [f"- `{a}`" for a in arts] if arts else ["None."]
    lines += ["", "## Parameters", "", "```json", json.dumps(result.get("params") or {}, indent=2),
              "```", "", NOTES_HEADING, ""]
    lines.append(notes.strip() if notes and notes.strip() else
                 "_Add interpretation here; this section survives `fbench analyze`._")
    lines.append("")
    return "\n".join(lines)


def write_findings(run_dir: Path, result: dict[str, Any], failed: list[str] | None = None
                   ) -> Path:
    path = Path(run_dir) / "FINDINGS.md"
    notes = None
    if path.exists():
        text = path.read_text(encoding="utf-8")
        if NOTES_HEADING in text:
            notes = text.split(NOTES_HEADING, 1)[1]
            if "_Add interpretation here" in notes:
                notes = None
    path.write_text(render(result, failed, notes), encoding="utf-8")
    return path
